const long long ZERO = 0LL;
const long long INF64 = 1e18;
const int INF32 = 1e9;
const int MOD = 1e9 + 7;
const double PI = acos(-1.0L);
const double EPS = static_cast<double>(1e-9);
typedef long long ll;

int modCalc(int a) {
  return ((a % MOD) + MOD) % MOD;
}

int calcProduct(int a, int b) {
  return int(a * 1LL * b % MOD);
}

int fastPower(int a, int k) {
  int res = 1;
  while (k > 0) {
    if (k & 1) res = calcProduct(res, a);
    a = calcProduct(a, a);
    k >>= 1;
  }
  return res;
}

int computeInverse(int a) {
  int b = fastPower(a, MOD - 2);
  assert(calcProduct(a, b) == 1);
  return b;
}

struct Edge {
