  int capacity;
  int flow;
  int cost;

  Edge() {};

  Edge(int _y, int _capacity, int _flow, int _cost) 
    : y(_y), capacity(_capacity), flow(_flow), cost(_cost) {};
};

vector<Edge> edgesVec;

const int MAXNODES = 1e6 + 7;
vector<int> adjList[MAXNODES];

ll totalCostVal = 0;
ll distArr[MAXNODES];
int predArr[MAXNODES];
int peArr[MAXNODES];
int inQ[MAXNODES];

int sNode = MAXNODES - 2;
int tNode = MAXNODES - 1;

int residual(int x) {
  return edgesVec[x].capacity - edgesVec[x].flow;
}

void findAugmentFlow() {
  for (int i = 0; i < MAXNODES; i++) {
    distArr[i] = INF64;
    predArr[i] = -1;
    peArr[i] = -1;
    inQ[i] = 0;
  }
  distArr[sNode] = 0;
  std::queue<int> q;
  q.push(sNode);
  inQ[sNode] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    inQ[u] = 0;
    for (auto eIdx : adjList[u]) {
      if (!residual(eIdx)) continue;
      int cst = edgesVec[eIdx].cost;
      int y = edgesVec[eIdx].y;
      if (distArr[y] > distArr[u] + cst) {
        distArr[y] = distArr[u] + cst;
        predArr[y] = u;
        peArr[y] = eIdx;
        if (inQ[y] == 0) {
          inQ[y] = 1;
          q.push(y);
        }
      }
    }
  }
  int cur = tNode;
  while (cur != sNode) {
    edgesVec[peArr[cur]].flow++;
    edgesVec[peArr[cur] ^ 1].flow--;
    cur = predArr[cur];
  }
  totalCostVal += distArr[tNode];
}

void addEdgeToGraph(int x, int y, int cap, int cst) {
  adjList[x].push_back(edgesVec.size());
  edgesVec.emplace_back(y, cap, 0, cst);
  adjList[y].push_back(edgesVec.size());
  edgesVec.emplace_back(x, 0, 0, -cst);
}

